# configuration file /etc/nginx/sites-enabled/infraset-tls:
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    server_name node1;

    ssl_certificate     /etc/nginx/tls/server.crt;
    ssl_certificate_key /etc/nginx/tls/server.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_tickets off;

    root /var/www/html;
    index index.html;

    location = /healthz {
        default_type text/plain;
        return 200 "certificate-rotation-ready\n";
    }

    location = /continuity.bin {
        limit_rate 20k;
        try_files $uri =404;
    }
}
--- config file metadata ---
root:root 644 /etc/nginx/sites-available/infraset-tls
root:root 777 /etc/nginx/sites-enabled/infraset-tls
